UNION ALL
SELECT 3504, 3378, 27, 5, 'the food was awesome and staff as well!! very clean!!', '2021-03-03 18:05:22', NULL
UNION ALL
SELECT 3505, 3379, 27, 3, 'This subway is below average, hence the three star rating. I have been here many times, which is why it is getting three and not two. They have definitely been increasing their quality, and I will revise the star rating if it changes. It just seems like they can''t keep competent employees that can make subs quick and properly. It is in a convenient location though.', '2020-02-21 20:57:54', NULL
UNION ALL
SELECT 3506, 3380, 27, 4, 'Subway in Verona Va the people have alway been nice and friendly.', '2020-03-12 12:16:03', NULL
UNION ALL
