SELECT 3790, 3658, 44, 5, CONVERT(X'5175697465206120706c656173616e7420737572707269736520666f72204c757261792e20536d616c6c2c20636f7a79206561746572792e20506c656e7479206f66206272756e6368206f7074696f6e7320666f7220616e792070616c6174652e0a0a537472656574207061726b696e672e' USING utf8mb4), '2021-03-06 03:17:47', NULL
