INSERT INTO `Review` (`review_id`, `author_user_id`, `vendor_id`, `rating`, `review_text`, `created_at`, `updated_at`)
SELECT batch.* FROM (
SELECT 4301 AS `review_id`, 4150 AS `author_user_id`, 49 AS `vendor_id`, 5 AS `rating`, 'Great food. All food homemade at restaurant. Generous amount of food. Prices are good to' AS `review_text`, '2019-04-09 17:51:04' AS `created_at`, NULL AS `updated_at`
UNION ALL
SELECT 4302, 4151, 49, 5, 'Great place to eat. Yummy food and great service.', '2019-07-28 06:13:57', NULL
UNION ALL
SELECT 4303, 4152, 49, 5, 'I really enjoy eating here.', '2020-03-12 01:17:18', NULL
UNION ALL
SELECT 4304, 4153, 49, 5, 'Service was good , food was fresh.  Will definitely be back.', '2019-07-13 12:11:51', NULL
UNION ALL
SELECT 4305, 4154, 49, 5, 'Great place to eat.we love it', '2020-07-11 01:15:50', NULL
UNION ALL
SELECT 4306, 4155, 49, 5, 'This is both Dr. Autumn Starnes and my favorite place to eat in Norton.  The Italian dishes are amazing, salads are fresh and big, Calzone and Stromboli are both amazing with the great meat sauce.  You should not think of this as ANOTHER pizza place (although the thick crust or Sicilian pizzas are my favorites) this IS the local ITALIAN restaurant.  I would compare this to Olive Garden not Dominos''!  Our concerns with local restaurants are consistency and service.  The consistency is the best around.  The service has been a concern in the past but they have a new manager of the wait-staff and now we believe it is second to none.  Please try these guys out again if you have had concerns in the past and if you have never been there, well, you are in for a treat.', '2019-07-22 01:14:32', NULL
UNION ALL
SELECT 4307, 4156, 49, 5, 'Excellent food an Excellent an friendly service by Lisa Thank you..', '2019-10-08 23:59:44', NULL
UNION ALL
SELECT 4308, 4157, 49, 5, 'Locally owned and operated. Great Italian food, gluten free choices. Yum.', '2019-02-15 15:09:19', NULL
UNION ALL
SELECT 4309, 4158, 49, 4, 'Love,  love the gnocchi saporti! Must agree with previous reviews about the food being good and the service a bit slow.  Disappointed that the garlic knots are off the menu,  they were fantabulous! Recommend checking this place out as long as you have plenty of time.', '2018-12-15 21:40:14', NULL
UNION ALL
SELECT 4310, 4159, 49, 4, 'Great atmosphere! food tastes fresh. Wish the bread wasn''t a basic small loaf and would love to see more side items.', '2017-05-01 21:03:51', NULL
UNION ALL
SELECT 4311, 4160, 49, 5, 'Good food good service.', '2019-07-27 14:26:52', NULL
UNION ALL
SELECT 4312, 4161, 49, 3, 'Good pizza ...ok pasta...good salad and bread....subs are really good', '2019-03-22 00:01:42', NULL
UNION ALL
SELECT 4313, 4162, 49, 5, 'Great food if you''re not in a hurry. If you is an issue it''s the wrong place. Staff is friendly & great.', '2017-09-13 23:50:24', NULL
UNION ALL
SELECT 4314, 4163, 49, 4, 'Good food good service.', '2019-03-24 17:32:13', NULL
UNION ALL
