UNION ALL
SELECT 4316, 4165, 49, 5, 'Great Food, friendly service, clean restaurant', '2018-12-03 17:22:40', NULL
UNION ALL
SELECT 4317, 4166, 49, 5, 'Food is always excellent and fresh!!!', '2019-12-18 13:27:00', NULL
UNION ALL
