UNION ALL
SELECT 4468, 4305, 16, 5, 'Random Thursday, and we had to wait. Almost 30 minutes for a table for 2. That tells you everything you need to know about Tommy''s. Good old-school diner food.', '2021-01-14 23:58:31', NULL
UNION ALL
SELECT 4469, 4306, 16, 3, 'This visit wasn''t the best for sure. Our server definitely was not in a good mood and the meal and service was rushed.', '2021-02-20 16:47:36', NULL
UNION ALL
