SELECT 7339, 7042, 9, 5, 'Bringing their apple pie to Thanksgiving dinner has become an annual tradition for us.  Be sure to buy an extra one for yourself or when you get it home it may not last until Thanksgiving.', '2020-11-25 20:50:18', NULL
UNION ALL
SELECT 7340, 7043, 9, 5, 'My first time here and I''m very happy, this young workers are very friendly and professionals...food is really amazing! Come over for good German goodies🇩🇪🇩🇪', '2020-02-22 22:17:10', NULL
UNION ALL
SELECT 7341, 7044, 9, 5, 'The staff are very attentive. They will even help you take out your order to your car if you can''t carry it by yourself.', '2020-11-02 04:29:38', NULL
UNION ALL
