UNION ALL
SELECT 7398, 7096, 9, 5, 'A taste of German bakery (and sausages) - baked using German recipes and imported things like Stollen', '2019-11-17 01:59:31', NULL
UNION ALL
SELECT 7399, 7097, 9, 5, 'All the items I''ve tried here so far have been super tasty. They also do fun events. During my last visit they had an open kitchen allowing you to walk through and see all the baking, have some free samples, and try you hand at making a few things yourself!', '2017-09-30 19:39:34', NULL
