SELECT 7860, 7524, 53, 4, 'Smokey little Mom and Pop dive. Great for what it is if that''s what you''re into. Staff are warm and friendly, I''ll definitely be back.', '2019-11-08 22:43:51', NULL
UNION ALL
SELECT 7861, 1215, 53, 4, 'Bubbas is a fun place to go get a few beers and some good food. The beers are cheap compared to other local spots and the food is cooked with a little love. Most of the people are friendly but like any bar it can get a little rowdy after midnight. Not every night but we all know how alcohol always gets the best of atleast one person. They do allow smoking in there so if that bothers you, this might not be the place for you.', '2019-10-20 17:22:52', NULL
UNION ALL
SELECT 7862, 7525, 53, 5, 'It''s a very nice place to eat & have drinks with great customer service & a great cook!', '2020-03-06 01:01:40', NULL
UNION ALL
