UNION ALL
SELECT 8431, 8039, 19, 5, 'Great burgers and shakes. I really appreciated that an employee came by our table to make sure everything was good, he even asked if there was anything he could get us. Fantastic customer service! Looking forward to going back.', '2018-11-21 01:25:24', NULL
