SELECT 8461, 8069, 19, 5, '1st timer. Drive through was quick, and service was friendly and efficient! Ice cream tasted good.', '2019-04-02 00:09:33', NULL
UNION ALL
SELECT 8462, 8070, 19, 4, 'The frozen custard confections are the best. Sundaes, concrete (all the ingredients mixed in), and milkshakes in every flavor they offer -  and there''s a long list!  My favorite sandwich at Freddys is the #5, kind of a patty melt on grilled toast.  Well worth a try next time you go. I''ve also liked every seasonal special; so keep an eye out for those.', '2018-04-18 01:56:01', NULL
UNION ALL
