INSERT INTO `Review` (`review_id`, `author_user_id`, `vendor_id`, `rating`, `review_text`, `created_at`, `updated_at`)
SELECT batch.* FROM (
SELECT 10001 AS `review_id`, 9522 AS `author_user_id`, 3 AS `vendor_id`, 5 AS `rating`, '' AS `review_text`, '2020-09-29 10:28:52' AS `created_at`, NULL AS `updated_at`
UNION ALL
SELECT 10002, 9523, 3, 5, '', '2018-12-07 18:23:19', NULL
UNION ALL
SELECT 10003, 9524, 3, 5, '', '2019-07-29 00:57:08', NULL
UNION ALL
SELECT 10004, 9525, 59, 5, 'This is a fantastic Jersey Mike’s location. I’ve been here a few times over the past months and have never had anything but a great sandwich and service!  The staff and the lead manager are super and very courteous. The restaurant is clean and do their best to keep it that way. I highly recommend this Jersey Mike’s restaurant location to anyone passing through this area.', '2019-01-13 01:33:35', NULL
UNION ALL
SELECT 10005, 9526, 59, 5, 'Placed a pick up order. Our subs were ready on time. They were absolutely delicious. Jersey Mike''s is consistently delicious. This time though the bread was just extra soft and the banana peppers and lettuce seemed crisper than usual. It was phenomenal!', '2020-12-23 23:19:52', NULL
UNION ALL
SELECT 10006, 9527, 59, 5, 'Very clean and highly professionally run.  The staff there is courteous and enthusiastic.  Best run restaurant in King George.', '2021-02-11 15:46:42', NULL
UNION ALL
SELECT 10007, 9528, 59, 5, 'Order is always correct and ready to pickup when I order online.', '2020-12-19 23:30:25', NULL
UNION ALL
SELECT 10008, 9529, 59, 5, CONVERT(X'' USING utf8mb4), '2020-06-11 01:03:16', NULL
UNION ALL
SELECT 10009, 9530, 59, 5, 'Italian sub Mike''s Way, was wonderful', '2021-03-26 22:52:25', NULL
UNION ALL
SELECT 10010, 9531, 59, 5, 'The only good place to eat in Dahlgren....', '2020-10-14 00:23:55', NULL
UNION ALL
SELECT 10011, 9532, 59, 4, 'Love Jersey Mike''s #13, Mike''s Way, juice on the side.  I think the bread has changed since I first started frequenting this chain, and I don''t think it''s quite as good as it used to be...  only reason I didn''t give 5 stars though it''s still a great sub', '2020-02-28 17:45:55', NULL
UNION ALL
SELECT 10012, 9533, 59, 5, 'The sub was good but the customer service was excellent I even gave a tip.', '2020-06-22 21:59:24', NULL
UNION ALL
SELECT 10013, 9534, 59, 5, 'I don''t give max ratings often. This location is always great. The subs are the best in the area by far (roast beef is my favorite) and the service is fantastic! The quality of the establishment is shown in the line that can sometimes go out the door during lunch, but the wait is always worth it and the online ordering system is very convenient.', '2019-04-12 03:20:46', NULL
UNION ALL
SELECT 10014, 9535, 59, 5, 'Great service and food, convenient location.', '2020-10-12 23:27:22', NULL
UNION ALL
SELECT 10015, 9536, 59, 5, 'They always go above and beyond I have allergies and they are great when making my food so I feel comfortable that I won''t have a reaction.', '2020-02-08 18:41:05', NULL
UNION ALL
SELECT 10016, 9537, 59, 4, 'You can''t go wrong with this place.  I ordered a pickle from the jar as well and the employee fished out the biggest one for me.  I guess he saw the desire in my eyes.  Great service!', '2019-07-22 02:00:39', NULL
UNION ALL
SELECT 10017, 9538, 59, 4, 'Staff is cheerful despite the challenges of our pandemic paradise.', '2020-07-15 18:09:01', NULL
UNION ALL
SELECT 10018, 9539, 59, 5, 'People are super nice love this location', '2020-08-27 14:02:00', NULL
UNION ALL
SELECT 10019, 9540, 59, 5, 'Love  love it  food  was good  and hot haven''t  try the  wraps or cold sandwiches yet.', '2019-11-23 13:13:10', NULL
UNION ALL
SELECT 10020, 9541, 59, 3, 'The foods pretty good but a bit pricey', '2020-01-25 21:26:45', NULL
UNION ALL
SELECT 10021, 9542, 59, 3, 'Honestly, I like the way their subs taste and the staff is always friendly and courteous. However, the last two times I went it was over $13 for a mini sub, chips and drink with a small tip. Overpriced in my opinion and won''t be going back!', '2019-07-24 00:05:52', NULL
UNION ALL
SELECT 10022, 210, 59, 1, 'Found 4 small bones in the steak and cheese.  Called and told them about it and took it back and showed them. They were very nice about it, but I will probably not go back.', '2019-02-12 03:35:47', NULL
UNION ALL
SELECT 10023, 9543, 59, 4, 'Tasty sandwiches, though a little pricey compared to similar offerings. Fairly quick service, esp when one orders cold-cuts.', '2019-05-19 03:41:08', NULL
