UNION ALL
SELECT 10518, 9994, 4, 5, 'So good, stop by and enjoy a kupkake or a sandwich. You''ll be glad you did. Great service,  they have so much going on, so much to offer.', '2017-09-23 03:37:25', NULL
UNION ALL
SELECT 10519, 9995, 4, 3, 'Delicious baked goods, friendly service, a bit pricey.', '2018-10-07 21:56:11', NULL
