SELECT 10801 AS `review_id`, 6063 AS `author_user_id`, 61 AS `vendor_id`, 5 AS `rating`, 'Been visiting this location for years, it has consistently had great service and great food.  If you''re looking for a different take on chicken wings this is definitely the place you should visit.' AS `review_text`, '2020-01-16 00:59:30' AS `created_at`, NULL AS `updated_at`
UNION ALL
