SELECT 10803, 6080, 61, 5, 'Had the bulgogi tacos for the first time today. They were delicious!!! Will definitely have them again.', '2020-10-05 23:35:41', NULL
UNION ALL
SELECT 10804, 10243, 61, 5, 'I usually call my order in and pick it up. The food is so good and absolutely on point every time.  This location is very interesting and should be visited at least once!', '2020-03-20 04:25:53', NULL
UNION ALL
