SELECT 11692, 11027, 62, 3, 'This was my first experience and only experience with Cava.  The food was good.  The flavors were a bit overwhelming.  The staff were not friendly or helpful.  It was like they expected us to know what the offerings were even after we explained it was our first visit.  They were not even busy at the time.  My daughter''s barely ate their meals.  It was also pricey.', '2018-09-04 02:15:43', NULL
UNION ALL
SELECT 11693, 11028, 62, 5, 'My son was showing us around Charlotsville and we stopped at CAVA for Mediterrean theme lunch. The place was very efficient and offered lots of enticing choices. We were given a menu in line which made it easier for first timers. I had lamb meatballs in a grains and greens bowl with a delicious sauce. The meal was very filling, good value and tasty.  Definitely a quality food recommendation. A little bigger scoop of hummus would have been nice.', '2018-11-21 14:04:01', NULL
UNION ALL
SELECT 11694, 11029, 62, 5, 'Always delicious fresh ingredients', '2020-06-09 22:23:28', NULL
UNION ALL
SELECT 11695, 11030, 62, 5, 'Service extraordinary!  Food great too!', '2019-08-30 01:26:16', NULL
UNION ALL
SELECT 11696, 11031, 62, 5, 'Quick and tasty Mediterranean style food! Easy to order and go with the app. Easily a go to for a delicious, healthy meal.', '2018-08-28 15:37:36', NULL
UNION ALL
SELECT 11697, 11032, 62, 5, 'Great meal.  Best way to describe it is Mediterranean chipotle.', '2019-05-14 03:21:21', NULL
UNION ALL
SELECT 11698, 11033, 62, 5, 'This place has delicious food! Five stars for vegan options. We need one Chesapeake VA.', '2018-10-15 17:49:10', NULL
UNION ALL
SELECT 11699, 11034, 62, 5, 'Great food, amazing team, We need you guys in Harrisonburg VA.', '2019-06-06 12:27:01', NULL
UNION ALL
SELECT 11700, 11035, 62, 5, 'Unbeatable taste and nutrition at the price point, location and staff are solid too!', '2019-03-05 02:52:45', NULL
) AS batch WHERE @cs4750_seed_allowed=1;
