SELECT 12888, 12044, 24, 4, 'Decided to have Sunday lunch here. Had not visited in a while, but will be back soon. Good customer service, and the food was delicious. They also have a large selection of craft beers. If you''re looking for a good BBQ experience then give this place a try.', '2019-03-10 15:58:39', NULL
UNION ALL
SELECT 12889, 12045, 24, 5, 'Honey bourbon wings😍😍😍😍my husband actually asked to meet the chef...it was that good', '2021-03-28 23:48:31', NULL
UNION ALL
