UNION ALL
SELECT 12894, 12050, 24, 5, 'The food was fantastic and always is. Their wings are my favorite wings in Hampton Roads hands down! The server we had, Alex, was fantastic! On it and eager to serve and make sure we had a great visit! Thankful this is around the corner because with the atmosphere, bar, BBQ and wings you can''t go wrong!', '2020-03-12 00:53:46', NULL
UNION ALL
SELECT 12895, 12051, 24, 5, 'Simply one of the best!! Good beer, good atmosphere, service is pretty good. If you like your meats and beer this place should be on your list!', '2020-12-12 12:00:51', NULL
UNION ALL
SELECT 12896, 6431, 24, 5, 'Awesome place to eat!!! Food is delicious and we had a wonderful waitress.', '2021-02-27 23:14:19', NULL
