UNION ALL
SELECT 14378, 13218, 6, 3, 'The food is pretty good and the service is usually pretty good too but it''s just slow.  I''ve never got out of there in less than hour even at lunch.  Doesn''t matter if its busy or not the kitchen is always slow.', '2019-01-03 22:26:29', NULL
UNION ALL
SELECT 14379, 13219, 6, 3, 'The food was delicious. The service was great.  The steak was not as tender as other steak restaurants in the area. The dining room could have been cleaner since they were not very busy when we came in.', '2018-09-21 23:08:56', NULL
