SELECT 14394, 13232, 6, 4, 'For mgmt. Service was great. Courses of food were above average. Except for the rolls. Not good. Received replacements still not good.', '2019-06-08 19:04:46', NULL
UNION ALL
SELECT 14395, 13233, 6, 5, 'Great service.. knowledge of menu and prices..', '2019-08-14 19:34:29', NULL
UNION ALL
