UNION ALL
SELECT 14397, 12245, 6, 3, 'Missed the entrance heading east on 10, store front sign was not lit up and the entrance to the parking lot was actually closer to the Hooters. Burger was extra well done when ordered well, spouse''s chicken was good and kids meals were as expected. Staff was well mannered and as snappy as the kitchen would allow. Don''t expect great things, expect am average meal from a chain.', '2017-12-28 00:27:11', NULL
UNION ALL
SELECT 14398, 13235, 6, 3, 'The server was great. The food wasn''t all that flavorful. We had two things wrong with our order. Undercooked steak, wrong side.', '2019-03-11 00:51:13', NULL
