SET @cs4750_seed_ok=(@cs4750_seed_allowed=1 AND (SELECT COUNT(*) FROM `User`)=13958 AND (SELECT COUNT(*) FROM `Vendor`)=81 AND (SELECT COUNT(*) FROM `Cuisine`)=24 AND (SELECT COUNT(*) FROM `Location`)=75 AND (SELECT COUNT(*) FROM `OperatingHours`)=531 AND (SELECT COUNT(*) FROM `Review`)=15218 AND (SELECT COUNT(*) FROM `Photo`)=1864 AND (SELECT COUNT(*) FROM `VendorCuisine`)=100 AND (SELECT COUNT(*) FROM `VendorBase`)=75 AND (SELECT COUNT(*) FROM `OperatingStop`)=324 AND (SELECT COUNT(*) FROM `MenuItem`)=243 AND (SELECT COUNT(*) FROM `FoodPermit`)=81 AND (SELECT COUNT(*) FROM `Manages`)=89 AND (SELECT COUNT(*) FROM `Favorites`)=144 AND (SELECT COUNT(*) FROM `ReviewPhoto`)=1621 AND (SELECT COUNT(*) FROM `MenuItemPhoto`)=243 AND NOT EXISTS(SELECT 1 FROM Photo p JOIN ReviewPhoto rp ON p.photo_id=rp.photo_id JOIN Review r ON rp.review_id=r.review_id WHERE p.vendor_id<>r.vendor_id) AND NOT EXISTS(SELECT 1 FROM Photo p JOIN MenuItemPhoto mp ON p.photo_id=mp.photo_id JOIN MenuItem m ON mp.menu_item_id=m.menu_item_id WHERE p.vendor_id<>m.vendor_id));
SET @cs4750_finish_sql=IF(@cs4750_seed_ok,'COMMIT','ROLLBACK');
PREPARE cs4750_finish FROM @cs4750_finish_sql;
EXECUTE cs4750_finish;
DEALLOCATE PREPARE cs4750_finish;
SELECT IF(@cs4750_seed_ok,'SUCCESS: all tables populated and committed','NOT IMPORTED: existing data or failed checks; transaction rolled back') AS import_status;
SET SESSION sql_mode=@cs4750_saved_mode;
SET SESSION time_zone=@cs4750_saved_timezone;
SET SESSION autocommit=@cs4750_saved_autocommit;
SELECT 'User' AS table_name, COUNT(*) AS row_count FROM `User` UNION ALL
SELECT 'Vendor' AS table_name, COUNT(*) AS row_count FROM `Vendor` UNION ALL
SELECT 'Cuisine' AS table_name, COUNT(*) AS row_count FROM `Cuisine` UNION ALL
SELECT 'Location' AS table_name, COUNT(*) AS row_count FROM `Location` UNION ALL
SELECT 'OperatingHours' AS table_name, COUNT(*) AS row_count FROM `OperatingHours` UNION ALL
SELECT 'Review' AS table_name, COUNT(*) AS row_count FROM `Review` UNION ALL
SELECT 'Photo' AS table_name, COUNT(*) AS row_count FROM `Photo` UNION ALL
SELECT 'VendorCuisine' AS table_name, COUNT(*) AS row_count FROM `VendorCuisine` UNION ALL
SELECT 'VendorBase' AS table_name, COUNT(*) AS row_count FROM `VendorBase` UNION ALL
SELECT 'OperatingStop' AS table_name, COUNT(*) AS row_count FROM `OperatingStop` UNION ALL
SELECT 'MenuItem' AS table_name, COUNT(*) AS row_count FROM `MenuItem` UNION ALL
SELECT 'FoodPermit' AS table_name, COUNT(*) AS row_count FROM `FoodPermit` UNION ALL
SELECT 'Manages' AS table_name, COUNT(*) AS row_count FROM `Manages` UNION ALL
SELECT 'Favorites' AS table_name, COUNT(*) AS row_count FROM `Favorites` UNION ALL
SELECT 'ReviewPhoto' AS table_name, COUNT(*) AS row_count FROM `ReviewPhoto` UNION ALL
SELECT 'MenuItemPhoto' AS table_name, COUNT(*) AS row_count FROM `MenuItemPhoto`;
